import { createSpaceScene } from './space-scene.js';
import { PlaybackClock, sampleManeuver } from './playback.js';
import { calculate, advanceFlight, remainingDv, flightChoices, summarize } from './engine.js';

const $=s=>document.querySelector(s);
const number=n=>Math.round(n).toLocaleString('en-US');
const reduce=window.matchMedia('(prefers-reduced-motion: reduce)');
const settings={view:'follow',rate:1,motion:!reduce.matches,exploded:false,rotation:0,auto:true};
let scene=null,cleanup=[],playback=null,raf=0,signalFrame=0,disposer=null;
const glyph={pause:'Ⅱ',play:'▶',reset:'↺',expand:'⛶',arrow:'↗'};
export function hangarMarkup(design,missionId,category){return `<div class="hangar-experience"><div class="scene-topline"><span><i class="live-dot"></i> SPACECRAFT ASSEMBLY</span><span class="scene-chip">CONFIGURATION MODEL</span></div><div class="space-scene hangar-scene" id="hangar-scene" tabindex="0" role="group" aria-label="Interactive 3D spacecraft. Drag to rotate, use arrow keys to change view, or select a system below."><div class="scene-loading"><span class="loading-orbit"></span>Assembling spacecraft…</div></div><div class="hangar-overlay"><span>HAIL MARY / ENGINEERING BAY</span><small>DRAG TO ORBIT · CLICK A COMPONENT</small></div><div class="hangar-controls"><button type="button" data-experience="explode" aria-pressed="${settings.exploded}">⊞ Exploded view</button><button type="button" data-experience="auto" aria-pressed="${settings.auto}">↻ Auto-rotate</button><button type="button" data-experience="reset">↺ Reset view</button><label>ROTATION <input type="range" min="-180" max="180" step="1" value="${settings.rotation}" data-experience="rotate" aria-label="Rotate spacecraft"/></label></div><div class="hangar-note">Select a system below or click its 3D component to inspect it. Concept model; hardware dimensions are illustrative.</div></div>`;}
export function flightSceneMarkup(f){const result=summarize(f);return `<div class="cinema" id="flight-cinema"><div class="cinema-header"><span class="scene-topline"><i class="live-dot"></i> MISSION VISUALIZER</span><span class="scene-chip" id="cinema-status">${f.complete?(f.failed?'SIGNAL LOST':'FLIGHT COMPLETE'):'COMMAND STANDBY'}</span></div><div class="space-scene flight-scene" id="flight-scene" tabindex="0" role="group" aria-label="Interactive 3D Earth to Moon mission. Drag or use arrow keys to orbit the camera. Camera buttons are below."><div class="scene-loading"><span class="loading-orbit"></span>Loading trajectory…</div></div><div class="cinema-vignette"></div>${f.complete?`<div class="game-result ${result.objectiveMet?'victory':'defeat'}" role="status"><span>${result.objectiveMet?'MISSION SUCCESS':'MISSION FAILED'}</span><strong>${f.outcome==='impact'?'Surface impact':f.outcome==='escape'?'Trajectory lost':result.objectiveMet?(f.missionId==='lander'?'Touchdown confirmed':f.missionId==='orbiter'?'Lunar orbit secured':'Flyby complete'):'Science target missed'}</strong><p>${f.failed?f.failureReason:`${result.science.toFixed(1)} / ${calculate(f.design,f.missionId,f.mode).mission.minScience} science points returned`}</p><button class="button primary" data-action="retry-flight">Fly again</button><button class="button secondary" data-action="refine">Modify spacecraft</button></div>`:''}<div class="cinema-headline"><span id="scene-phase">${['EARTH PARKING ORBIT','TRANSLUNAR COAST','DEEP SPACE OPERATIONS','LUNAR APPROACH','LUNAR SCIENCE','MISSION COMPLETE'][f.step]}</span><strong id="scene-caption">${['Departure burn pending.','Check the outbound trajectory.','Resolve the power anomaly.','Confirm the arrival burn.','Schedule the science downlink.','Review the flight record.'][f.step]}</strong></div><div class="scene-reticle" aria-hidden="true"><i></i><i></i><i></i><i></i></div><div class="scene-coordinate">SOL / TERRA — LUNA<br><span>ILLUSTRATIVE 3D · DISTANCES NOT TO SCALE</span></div><div class="scene-readouts"><div><small>PROP REMAINING</small><strong data-live="fuel">${number(f.fuel)}<em>kg</em></strong></div><div><small>VELOCITY RESERVE</small><strong data-live="dv">${number(remainingDv(f))}<em>m/s</em></strong></div></div><div class="maneuver-overlay" id="maneuver-overlay" hidden><span id="maneuver-label">Executing command</span><strong id="maneuver-percent">0%</strong><div class="maneuver-track"><i id="maneuver-fill"></i></div><small id="maneuver-detail">Preparing maneuver playback</small></div><div class="countdown" id="launch-countdown" hidden aria-hidden="true">3</div><div class="cinema-controls"><div class="camera-presets" role="group" aria-label="Camera view">${[['overview','Orbit'],['follow','Follow'],['moon','Lunar']].map(([id,label])=>`<button data-experience="camera" data-view="${id}" aria-pressed="${settings.view===id}">${label}</button>`).join('')}</div><div class="transport-controls"><button data-experience="pause" aria-label="Pause animation" aria-pressed="false">${glyph.pause}</button><button data-experience="speed" aria-label="Playback speed">${settings.rate}×</button><button data-experience="motion" aria-pressed="${settings.motion}" aria-label="Ambient motion">✦</button><button data-experience="fullscreen" aria-label="Expand flight view">${glyph.expand}</button></div></div><div class="cinema-bottom"><span id="playback-hint">Drag to look around · keys 1–3 select a command</span><button data-experience="skip" disabled>Skip animation →</button></div></div>`;}
function listen(element,event,handler,options){if(!element)return;element.addEventListener(event,handler,options);cleanup.push(()=>element.removeEventListener(event,handler,options));}
function animateCounters(){if(!settings.motion)return;document.querySelectorAll('.result-hero .score-ring strong').forEach(el=>{const final=Number(el.textContent),start=performance.now();const tick=now=>{if(!el.isConnected)return;const p=Math.min(1,(now-start)/1200);el.textContent=Math.round(final*(1-Math.pow(1-p,3)));if(p<1)signalFrame=requestAnimationFrame(tick);};signalFrame=requestAnimationFrame(tick);});}
export function mountExperience({state,flight,onSelectCategory}){
  const host=$('#hangar-scene')||$('#flight-scene');
  if(host){const hangar=host.id==='hangar-scene';scene=createSpaceScene(host,{kind:hangar?'hangar':'flight',design:hangar?state.design:flight.design,missionId:hangar?state.missionId:flight.missionId,step:hangar?0:flight.step,motion:settings.motion,onSelect:onSelectCategory,onReady:()=>host.querySelector('.scene-loading')?.remove()});
    if(hangar){scene?.setExploded(settings.exploded);scene?.setRotation(settings.rotation);scene?.setAuto(settings.auto&&settings.motion);scene?.selectSystem(state.category);}else {scene?.setView(settings.view);if(flight.complete)scene?.setSample({route:flight.failed?[0,.25,.51,.77,1,1][flight.step]:1,outcome:flight.outcome,eventProgress:1,originRoute:[0,.25,.51,.77,1,1][flight.step]});}
  }
  listen(document,'click',async e=>{const button=e.target.closest('[data-experience]');if(!button||button.disabled)return;const action=button.dataset.experience;
    if(action==='camera'){settings.view=button.dataset.view;scene?.setView(settings.view);document.querySelectorAll('[data-experience="camera"]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===settings.view)));}
    if(action==='explode'){settings.exploded=!settings.exploded;if(settings.exploded){settings.auto=false;$('[data-experience="auto"]')?.setAttribute('aria-pressed','false');}scene?.setExploded(settings.exploded);button.setAttribute('aria-pressed',String(settings.exploded));}
    if(action==='auto'){settings.auto=!settings.auto;scene?.setAuto(settings.auto&&settings.motion);button.setAttribute('aria-pressed',String(settings.auto));}
    if(action==='reset'){settings.exploded=false;$('[data-experience="explode"]')?.setAttribute('aria-pressed','false');settings.rotation=0;settings.auto=true;scene?.reset();const slider=$('[data-experience="rotate"]');if(slider)slider.value=0;$('[data-experience="auto"]')?.setAttribute('aria-pressed','true');}
    if(action==='pause'){const paused=button.getAttribute('aria-pressed')!=='true';button.setAttribute('aria-pressed',String(paused));button.setAttribute('aria-label',paused?'Resume animation':'Pause animation');button.textContent=paused?glyph.play:glyph.pause;scene?.setPaused(paused);if(playback)playback.clock.paused=paused;$('#cinema-status').textContent=paused?'PLAYBACK PAUSED':playback?'MANEUVER ACTIVE':'COMMAND STANDBY';}
    if(action==='speed'){const speeds=[.5,1,2,4];settings.rate=speeds[(speeds.indexOf(settings.rate)+1)%speeds.length];button.textContent=`${settings.rate}×`;button.setAttribute('aria-label',`Playback speed: ${settings.rate} times`);playback?.clock.setRate(settings.rate);}
    if(action==='motion'){settings.motion=!settings.motion;scene?.setMotion(settings.motion);button.setAttribute('aria-pressed',String(settings.motion));if(!settings.motion&&playback)finishPlayback();}
    if(action==='skip')finishPlayback();
    if(action==='fullscreen'){const cinema=$('#flight-cinema');try{if(document.fullscreenElement)await document.exitFullscreen();else if(cinema.requestFullscreen)await cinema.requestFullscreen();else cinema.classList.toggle('expanded');}catch{cinema.classList.toggle('expanded');}}
  });
  listen(document,'input',e=>{if(e.target.dataset.experience==='rotate'){settings.rotation=Number(e.target.value);settings.auto=false;scene?.setRotation(settings.rotation);$('[data-experience="auto"]')?.setAttribute('aria-pressed','false');}});
  listen(host,'pointerdown',()=>{if(host?.id==='hangar-scene'){settings.auto=false;$('[data-experience="auto"]')?.setAttribute('aria-pressed','false');}});
  listen(document,'keydown',e=>{if(e.key==='Escape')$('#flight-cinema')?.classList.remove('expanded');});
  listen(reduce,'change',e=>{if(e.matches){settings.motion=false;scene?.setMotion(false);$('[data-experience="motion"]')?.setAttribute('aria-pressed','false');if(playback)finishPlayback();}});
  // Show the exact consequence of a choice before it is committed.
  const preview=$('#decision-preview');
  if(preview&&flight&&!flight.complete){const show=id=>{const choice=flightChoices(flight).find(c=>c.id===id);if(!choice)return;const next=advanceFlight(flight,id);const loss=flight.fuel-next.fuel;preview.innerHTML=`<span>COMMAND PREVIEW</span><strong>${choice.title}</strong><div><b>−${number(loss)} kg</b> propellant <b>${number(next.scienceFactor*100)}%</b> science retained <b>+${next.extraHours-flight.extraHours} h</b> schedule</div>`;};document.querySelectorAll('[data-action="flight-command"]').forEach(b=>{listen(b,'pointerenter',()=>show(b.dataset.id));listen(b,'focus',()=>show(b.dataset.id));});}
  listen(document,'keydown',e=>{
    if(e.repeat||e.ctrlKey||e.metaKey||e.altKey||document.querySelector('dialog[open]')||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;
    if(['1','2','3'].includes(e.key)&&state.view==='flight'&&!flight?.complete&&!playback){const b=document.querySelectorAll('[data-action="flight-command"]')[Number(e.key)-1];if(b&&!b.disabled){e.preventDefault();b.click();}}
  });
  animateCounters();
}
export function disposeExperience(){cancelAnimationFrame(raf);cancelAnimationFrame(signalFrame);playback=null;scene?.dispose();scene=null;cleanup.forEach(fn=>fn());cleanup=[];disposer?.();disposer=null;}
export function isPlaying(){return !!playback;}
function updateTelemetry(sample,before){const sciencePoints=$('[data-live="science-points"]');if(sciencePoints)sciencePoints.textContent=(calculate(before.design,before.missionId,before.mode).science*sample.science).toFixed(1);for(const el of document.querySelectorAll('[data-live="fuel"]'))el.innerHTML=`${number(sample.fuel)}<em>kg</em>`;for(const el of document.querySelectorAll('[data-live="dv"]'))el.innerHTML=`${number(sample.dv)}<em>m/s</em>`;
  const readouts=document.querySelectorAll('.telemetry-readout>strong');if(readouts[0])readouts[0].innerHTML=`${number(sample.fuel)}<span>kg</span>`;if(readouts[1])readouts[1].innerHTML=`${number(sample.dv)}<span>m/s</span>`;if(readouts[2])readouts[2].innerHTML=`${number(sample.power)}<span>W</span>`;const meter=$('.telemetry-readout .meter-track>i');if(meter)meter.style.width=`${sample.fuel/before.design.fuel*100}%`;const pairs=document.querySelectorAll('.telemetry-pair>strong');if(pairs[0])pairs[0].textContent=`${number(sample.science*100)}%`;if(pairs[1])pairs[1].textContent=`+${number(sample.hours)} h`;
}
function finishPlayback(){if(!playback)return;const p=playback;cancelAnimationFrame(raf);p.clock.finish();updateTelemetry(sampleManeuver(p.before,p.after,1),p.before);playback=null;p.onFinish();}
export function playManeuver({before,after,onFinish}){
  if(playback)return false;
  if(!settings.motion){onFinish();return true;}
  const clock=new PlaybackClock(after.failed?10:before.step===0?9:before.step===3?8:6);clock.setRate(settings.rate);playback={before,after,clock,onFinish};
  document.querySelectorAll('[data-action="flight-command"]').forEach(b=>{b.disabled=true;b.classList.toggle('chosen-command',b.dataset.id===after.decisions.at(-1));});
  const cinema=$('#flight-cinema');cinema?.classList.add('executing');$('#cinema-status').textContent='MANEUVER ACTIVE';$('#maneuver-overlay').hidden=false;$('#maneuver-label').textContent=after.log.at(-1).command;
  $('#playback-hint').textContent='Playback timing is compressed. Speed never changes physics.';$('[data-experience="skip"]').disabled=false;
  const pause=$('[data-experience="pause"]');pause.setAttribute('aria-pressed','false');pause.setAttribute('aria-label','Pause animation');pause.textContent=glyph.pause;scene?.setPaused(false);
  const preview=$('#decision-preview');if(preview)preview.setAttribute('aria-live','off');
  cinema?.scrollIntoView({behavior:reduce.matches?'instant':'smooth',block:'center'});$('[data-experience="pause"]')?.focus({preventScroll:true});
  let last=performance.now();const loop=now=>{if(!playback)return;const dt=document.hidden?0:Math.min(.1,(now-last)/1000);last=now;clock.tick(dt);const countIn=before.step===0?.22:0;const progress=Math.max(0,(clock.progress-countIn)/(1-countIn));const sample=sampleManeuver(before,after,progress);scene?.setSample(sample);updateTelemetry(sample,before);
    const counting=before.step===0&&clock.progress<countIn;$('#launch-countdown').hidden=!counting;if(counting)$('#launch-countdown').textContent=String(Math.max(1,Math.ceil((countIn-clock.progress)/countIn*3)));
    $('#maneuver-percent').textContent=`${Math.round(progress*100)}%`;$('#maneuver-fill').style.width=`${progress*100}%`;$('#maneuver-detail').textContent=sample.fullBurn?`${number(sample.burn)} / ${number(sample.fullBurn)} m/s commanded · ${number(before.fuel-sample.fuel)} kg consumed`:`Science retained ${number(sample.science*100)}% · schedule +${number(sample.hours)} h`;
    $('#scene-caption').textContent=after.outcome==='impact'?(progress<.65?'Uncontrolled descent. No braking thrust.':'Impact confirmed. Signal lost.'):after.outcome==='escape'?'Missed encounter. Leaving the mission corridor.':counting?'Stand by for ignition.':before.step===3?(before.missionId==='lander'?'Descent sequence underway.':before.missionId==='flyby'?'Closest approach. Eyes on the Moon.':'Braking into lunar orbit.'):before.step===4?'Bringing the science home.':sample.burning?'Burn in progress. Trajectory committed.':'Executing your flight plan.';
    if(clock.done){finishPlayback();return;}raf=requestAnimationFrame(loop);};raf=requestAnimationFrame(loop);return true;
}
